#!/usr/bin/env python3
"""Global Pulse: deterministic live-data patch and final UI cleanup."""
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parent
SNAP=ROOT/'update_snapshot.py'
INDEX=ROOT/'index.html'
GDELT_FEEDS='''    ("GDELT Live — Global", "https://api.gdeltproject.org/api/v2/doc/doc?query=(war%20OR%20conflict%20OR%20military%20OR%20sanctions%20OR%20election%20OR%20crisis)&mode=ArtList&format=rss&maxrecords=250&timespan=15m", "live"),
    ("GDELT Live — Africa", "https://api.gdeltproject.org/api/v2/doc/doc?query=(africa%20OR%20sudan%20OR%20congo%20OR%20sahel%20OR%20nigeria%20OR%20somalia)&mode=ArtList&format=rss&maxrecords=150&timespan=15m", "africa"),
    ("GDELT Live — Americas", "https://api.gdeltproject.org/api/v2/doc/doc?query=(mexico%20OR%20colombia%20OR%20venezuela%20OR%20brazil%20OR%20haiti%20OR%20ecuador%20OR%20peru)&mode=ArtList&format=rss&maxrecords=150&timespan=15m", "americas"),
    ("GDELT Live — Middle East", "https://api.gdeltproject.org/api/v2/doc/doc?query=(gaza%20OR%20iran%20OR%20israel%20OR%20yemen%20OR%20syria%20OR%20iraq)&mode=ArtList&format=rss&maxrecords=150&timespan=15m", "middle-east"),
'''
CSS='''<style id="gp-brand-live-css">.gp-brand-wrap{display:flex;align-items:baseline;gap:8px;min-width:0}.gp-brand-credit{font-size:9px;font-weight:650;letter-spacing:.08em;color:#70879c;white-space:nowrap}.gp-live-chip{display:inline-flex;align-items:center;gap:6px;margin-left:8px;padding:5px 8px;border:1px solid rgba(72,223,131,.22);border-radius:999px;background:rgba(72,223,131,.06);font-size:9px;color:#91a4b8}.gp-live-chip i{width:6px;height:6px;border-radius:50%;background:#48df83;box-shadow:0 0 0 3px rgba(72,223,131,.08)}#top{grid-auto-rows:max-content!important;align-items:start!important;min-height:0!important;height:auto!important;margin:0!important}#top>.panel{height:auto!important;min-height:0!important;margin:0!important}#top .bars{height:auto!important;min-height:0!important;margin:0!important;padding:0!important}.wrap{grid-auto-rows:max-content!important}.wrap>section{height:auto!important;min-height:0!important}.gp-web{height:440px;border:1px solid var(--line);border-radius:12px;background:#06101a;overflow:auto;color:var(--cyan);touch-action:pan-x pan-y}.gp-web svg{width:100%;height:100%;display:block;min-width:560px}.gp-web text{fill:var(--muted);font-size:9px;font-weight:700}.gp-node{cursor:pointer;outline:none}.gp-node circle{fill:#62a0ff;stroke:#eef5ff;stroke-width:1.2}.gp-node-political circle{fill:#aa8df7}.gp-node-economic circle{fill:#ffc857}.gp-node-strategic circle{fill:#3fc5ff}.gp-node:focus circle,.gp-node:hover circle{stroke:#48df83;stroke-width:2.5}.gp-web-controls{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:9px}.gp-web-controls input{flex:1;min-width:170px}.gp-web-controls select{min-width:155px;max-width:230px}.gp-web-count{font-size:10px;color:var(--muted);white-space:nowrap}.gp-web-detail{margin-top:9px;padding:10px;border:1px solid var(--line);border-radius:10px;background:#08131e;font-size:11px;color:var(--muted)}.gp-web-detail strong{color:var(--text)}.gp-web-links{display:grid;gap:6px;margin-top:7px}.gp-link-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:3px 8px;padding:7px 8px;border:1px solid var(--line);border-radius:7px}.gp-link-row span{color:var(--text)}.gp-link-row b{color:var(--blue)}.gp-link-row a{font-size:10px;font-weight:800}.gp-link-row small{grid-column:1/-1;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.gp-web-note{font-size:9px;color:var(--muted);margin-top:7px}.gp-layer-controls{display:grid;gap:8px;margin:0 0 11px}.gp-layer-tabs{display:flex;gap:6px;flex-wrap:wrap}.gp-layer-filters{display:flex;gap:7px;align-items:center}.gp-layer-filters input{flex:1;min-width:0}.gp-layer-filters select{border:1px solid var(--line);background:#09121c;color:var(--text);border-radius:9px;padding:8px 10px;min-height:36px}.gp-layer-count{font-size:10px;color:var(--muted);white-space:nowrap}.gp-layer-note{font-size:9px;color:var(--muted);line-height:1.45}.gp-layer-tabs .filter.active{border-color:var(--blue);background:rgba(98,160,255,.13);color:var(--blue)}@media(max-width:720px){.gp-brand-credit{font-size:8px}.gp-live-chip{display:none}.gp-web{height:390px}.gp-web-controls select{flex:1;min-width:130px;max-width:none}.gp-web svg{min-width:620px}.gp-layer-filters{align-items:stretch}.gp-layer-filters select{width:125px}.gp-layer-count{align-self:center}}</style>'''
AUTO_REFRESH='''<script id="gp-auto-refresh">(function(){"use strict";var PERIOD=60000,lastPage=location.href;function bustReload(){var u=new URL(lastPage,location.href);u.searchParams.set("gp_refresh",String(Date.now()));location.replace(u.href)}async function checkSnapshot(){try{var r=await fetch("data/snapshot.json?gp_check="+Date.now(),{cache:"no-store",headers:{"Cache-Control":"no-cache"}});if(!r.ok)return;var fresh=await r.json(),current=window.DATA&&window.DATA.updatedAt;if(current&&fresh.updatedAt&&fresh.updatedAt!==current)bustReload()}catch(e){}}window.gpForceRefresh=bustReload;setInterval(checkSnapshot,PERIOD);setTimeout(checkSnapshot,5000)})();</script>'''
ENHANCEMENTS='<script src="global_pulse_enhancements.js" defer></script><script src="global_pulse_graph.js" defer></script><script src="global_pulse_layers.js" defer></script><script src="global_pulse_v22.js" defer></script>'
def patch_snapshot():
 s=SNAP.read_text()
 if '"GDELT Live — Global"' not in s:
  pos=s.index('FEEDS = [')+len('FEEDS = [');s=s[:pos]+'\n'+GDELT_FEEDS+s[pos:]
 s=re.sub(r'unique\[:120\]','unique[:300]',s).replace('GlobalPulse/4.1','GlobalPulse/7.0');SNAP.write_text(s)
def patch_index():
 s=INDEX.read_text(encoding='utf-8')
 for pat in [r'<style id="gp-brand-live-css">.*?</style>',r'<script id="gp-auto-refresh">.*?</script>',r'<script src="global_pulse_enhancements\.js" defer></script>',r'<script src="global_pulse_graph\.js" defer></script>',r'<script src="global_pulse_layers\.js" defer></script>',r'<script src="global_pulse_v22\.js" defer></script>',r'<div class="gp-footer-credit">.*?</div>',r'<div class="gp-live-chip">.*?</div>',r'<span class="gp-brand-credit">.*?</span>']:s=re.sub(pat,'',s,flags=re.S)
 header='<header><div class="gp-brand-wrap"><div class="brand"><b>GLOBAL</b> PULSE</div><span class="gp-brand-credit">Made by J.S.</span></div><div class="live"><i id="liveDot"></i><span id="liveText">LOADING LIVE DATA</span></div><div class="gp-live-chip"><i></i>NEAR-LIVE OPEN DATA</div></header>'
 s,n=re.subn(r'<header>.*?</header>',header,s,count=1,flags=re.S)
 if n!=1:raise RuntimeError('Global Pulse header not found')
 s=re.sub(r'<title>.*?</title>','<title>Global Pulse — Global Conflict &amp; Intelligence Monitor</title>',s,count=1,flags=re.S)
 before,sep,after=s.partition(header);after=re.sub(r'\s*[·•-]?\s*Made by J\.S\.\s*',' ',after);s=before+sep+after
 s=s.replace('</head>',CSS+'</head>',1).replace('</body>',AUTO_REFRESH+ENHANCEMENTS+'</body>',1);INDEX.write_text(s,encoding='utf-8')
if __name__=='__main__':patch_snapshot();patch_index();print('Update 7 applied: live feeds, branding, auto refresh, production UI enhancements, intelligence web, reporting layers, and V2.2 trend/source monitoring.')
